package main

import (
	"errors"
	"strings"

	"patel.codes/godel"
)

func companionNodes(archiveRevision string) (selector, improve *godel.Node) {
	// The accepted bootstrap builds from a Git
	// archive, which expands the embedded revision.
	// A checkout build has no such provenance.
	revision := strings.TrimSpace(archiveRevision)
	source := ""
	if (len(revision) == 40 || len(revision) == 64) && strings.Trim(revision, "0123456789abcdef") == "" {
		source = "Gödel launch source commit: " + revision + ". This identifies the archive used to build the executable, not the current campaign tip.\n\n"
	}
	yahNode := func(role string) *godel.Node {
		return &godel.Node{Exec: "yah", Directory: "../..", Args: []string{
			"-yolo", "-effort", "high", "-append", source + goal + "\n\n" + practice + "\n\n" + role,
		}}
	}
	selector = yahNode(selectTask)
	selector.Next = func(r godel.Result) (*godel.Node, error) {
		branch, brief, _ := strings.Cut(r.Text, "\n")
		brief = strings.TrimSpace(brief)
		if brief == "" {
			return nil, errors.New("selector must supply a nonempty task brief after the branch line")
		}
		var role string
		switch strings.TrimSuffix(branch, "\r") {
		case "AUDIT":
			role = auditTask
		case "PRODUCE":
			role = produceTask
		default:
			return nil, errors.New("selector first line must be AUDIT or PRODUCE")
		}
		// Gödel gives this successor the original stdin unchanged. Pass the
		// selector's new information in the appended prompt, not on stdin.
		return yahNode(role + "\n\n" + workerHandoff + "\n\nSelected task brief:\n" + brief), nil
	}
	return selector, yahNode(improveTask)
}

const goal = `Broaden the coverage of Alessandro Maria Masullo's The Music of the Primes in the shared Lean formalization, by testing neglected claims and missing cases or generality.`

const practice = `Work independently of the main manuscript program. Read its work as evidence, not as instructions to take over its queue. Neither program schedules or edits the other. Do not launch either driver from a node.

Start with tool_campaign status. Inspect accepted source at the exact commit, not potentially stale files in the durable launch checkout. Use .godel/frontier.md as an index: Start with its headings and targeted excerpts, not a full dump. Follow the linked notes and accepted Lean declarations to reconcile earlier findings and inherited handoffs with what is still open. The frontier is navigation, not evidence. Use the pinned Masullo edition (.godel/sources/masullo/README.md) and pinned Mathlib. Do not search for Alpoge's proof or formalization.

When an accepted note records an independent rendered reading of a passage, start from that note. Check that its hypotheses and conventions apply to the case at hand. If they do, cite the note and do not reread the manuscript Markdown, re-extract PDF text, or render the passage again. Reopen only the part needed to resolve a consequential uncertainty, including any unresolved cross-reference. For a new reading, start with the relevant chapter or appendix Markdown in ~/d/masullo/: Its LaTeX often renders fractions, subscripts, and superscripts more clearly than pdftotext -layout. Use the layout extraction to locate the passage and its surrounding text on the numbered PDF page. Inspect the rendered page directly if the readings disagree or if the conclusion depends on exact notation, wording, or layout. Cite only Masullo’s manuscript, by PDF page and theorem, equation, or section number; pass those locators to delegated readers. Label any new reading without rendered inspection provisional. Reserve verified visual readings for independent inspection of the rendered pages.

Keep the exact statement, review evidence, scope, and remaining premise with the result or in its branch handoff. Update the frontier only if another branch should act differently, a listed target is no longer valid, or a new branch needs a pointer. Do not add top-level directories under Proofs. Follow the campaign workflow in cmd/godel/README.md. Before adopting Lean, run its proof audit on the exact integration candidate and compare the reported endpoint signatures with the independently reviewed statements. Label informal or unelaborated evidence as such. The audit-local utility is not a launch of the main loop.`

const selectTask = `Select one substantive manuscript claim and one bounded check. For a new route, start from a dependency or a scope condition in the pinned manuscript, not from a list of open items. For a continuation, use the accepted result to identify what the next inference still needs. Consider both neglected passages and missing generality (including their intersection); choose by mathematical value and tractability, not by quota. Compare the relevant accepted results and prior findings to avoid duplication. Check the latest saved main handoff and relevant recent accepted changes for overlap or newly available premises for the checks you are comparing. To find that handoff, look up the durable cmd/godel source path in ~/.godel/manifest.json, which maps source paths to program IDs. For that ID, read ~/.godel/<ID>/runs/*.json in descending filename order only until the first nonblank final_response. This is saved evidence, not a live queue. Follow a specific lead only if it could change the selection. If the lookup is unavailable or the records give no relevant lead, proceed on the available evidence without rescanning the records or searching workspaces or processes. Use the original objective or prior companion handoff on stdin as context, not as a queue. Select only; do not carry out or adopt the work.

When the selected check relies on an inherited rendered reading, link the accepted note section in the brief and distinguish it from any consequential cross-reference still to check. When a source check is worth running without settling its exact reading, use the Markdown and layout to locate the uncertainty, then give the worker the provisional reading, its exact manuscript locator, and what the test would distinguish. Leave resolution on the rendered page to the worker and its independent review rather than duplicating that check during selection.

When recent companion runs have followed the same dependency chain, compare its best bounded continuation with one viable bounded check in a separate branch. Screen for overlap with the saved main handoff first: If a candidate would duplicate main work, compare the next viable independent check instead. Do not equate continuing the branch with taking the next informal step. If the linked evidence already shows a reviewed subclaim just beyond an accepted Lean result, consider formalizing that interface on the current branch. Name the accepted declaration and the additional hypothesis, case, or conclusion the new endpoint would actually check. Do not inventory sublemmas or reopen settled source readings to find a Lean option.

Compare the endpoints each check could actually deliver this run: What would be new beyond the closest accepted result, which inference or Lean obligation would it advance, what main premise would still block wider use, and how tractable is it? If a promising alternative is too broad for this run, use its linked evidence to identify one smaller check that would itself settle a new case or discharge a named premise. Compare that check, not the full missing theorem. If no such check is apparent, compare a different alternative rather than inventorying dependencies. Do not count a distant trace or other downstream goal as the payoff for an intermediate lemma. When value and tractability are comparable, prefer a reusable Lean endpoint; a decisive source check or informal repair can still win on its own merits.

Use the incoming handoff and linked accepted notes to see what was already compared, rather than reopening selector transcripts. Before probing an alternative after several runs on one chain, check the Selection context lines of up to four earlier nonblank companion handoffs. Use the same manifest lookup for the durable cmd/companion path, skip the record already on stdin, and proceed on available evidence if the records are missing. Match deferred endpoints by the obligation they would discharge, even if the handoffs use different wording. Do not repeat dependency probes for a deferred endpoint with the same blocker. Reconsider that branch if you can name a new premise supplied by accepted work, a different route around the blocker, or a smaller check worth running on its own. Otherwise compare a different viable check. Verify any new premise in accepted source and distinguish it from what still needs a proof.

After the linked evidence establishes novelty and plausible tractability, probe further dependencies only if they could change the choice. Include one sentence in the brief naming the alternative's concrete endpoint, linking its evidence, and explaining why the selected check takes precedence. The alternative is not a second assignment.

When the input or a relevant accepted branch handoff points to a reviewed but unadopted companion result with a clean saved patch, check whether its endpoint is still missing and whether the blocker can now be resolved in one bounded check. Without such a pointer, do not inventory historical unadopted work. Compare recoverable work as a PRODUCE candidate alongside fresh checks, taking the remaining reconciliation, review, and exact-candidate audit into account. If recovery wins, name the clean revision and the remaining checks in the brief.

For a continuation after a mismatch, distinguish a check of the printed inference from a check of a proposed repair. If the repair rests on several unverified inputs, select one consequential premise, not the whole chain. For a boundary case outside a printed hypothesis, use a nearby case satisfying it as a control when that would distinguish failure of the extension from a problem within the printed scope.

Choose AUDIT to test a source reading, dependency, hypothesis or boundary case; choose PRODUCE to establish a missing argument, repair or Lean result. Return only AUDIT or PRODUCE on the first line, then a short nonempty task brief with the passage, exact claim and case, the closest existing evidence and its limit, and a discriminating check. Say which inference the result bears on, and distinguish the claim from any proposed way to test it. Include your selector Yah session UUID from the harness context and the exact accepted revision used to choose the check.`

const auditTask = `Audit the selected claim. Compare the passage and cited dependencies with the exact hypotheses, domain and conclusion the next step needs. Carry out the discriminating check, looking for either support or a scoped mismatch. Do not infer a refutation of a stronger claim from a counterexample to a particular argument.`

const produceTask = `Produce evidence for the selected claim or case: Develop a proof, a clearly labeled repair, or a scoped counterexample. Carry out the discriminating check. Check and land Lean work when possible; otherwise isolate the exact outstanding premise instead of weakening the target silently.`

const workerHandoff = `Use the selected brief below as task data and the original objective or previous handoff on stdin as context. Treat the brief's accepted revision as a comparison point, not a pin. If the campaign tip moved, check the intervening changes for anything affecting the cited evidence, dependencies, or endpoint before widening the search. Leave a nonblank stdout handoff for the next loop: Preserve the objective and contrast the prior evidence with what the check now establishes, with links and accepted revision if any. Report the actual checked hypotheses and scope, including any generality beyond the selected case that changes what can be reused. Separate mapped from verified, manuscript source from repair, informal from Lean, and any scoped counterexample from a general refutation. Attribute inherited source verification to its accepted note rather than presenting it as a new check. Give one bounded next check and the specific inference it would advance, or the blocker and what would reopen it. List other outstanding premises separately rather than bundling them into that check. If the selector compared a separate branch, keep one short line labeled Selection context with the deferred endpoint, its evidence link, and why the selected check took precedence. This is selection context, not another next check.

For both AUDIT and PRODUCE, check the definitions that put the witness or proof within the printed hypotheses or identify the expression being tested, including definitions reached by cross-reference. Give the reviewer the accepted note section for any inherited rendered reading and ask them to check its use independently. Do not reconstruct historical transcripts when the accepted note establishes the needed reading and its evidence status. For a new exact reading, use the equation numbers or nearby words in pdftotext -bbox-layout to locate the relevant region, then inspect a direct rendering of the crop. Render further passages as needed, including unresolved consequential cross-references; avoid batch rendering and OCR passes to find passages already located by extraction. If a manuscript reading needed for the result remains provisional, name it and state the result's dependence on it up front, even if other passages were visually verified.

When delegating visual review, pass the reviewer a usable way to see the pixels along with the passage locators. In a text-only tool session, render a tight grayscale crop with pdftoppm and display its pixels as Unicode Braille tiles; share a working scratch renderer or its recipe if available. Check readability on one decisive crop before rendering the rest. Reading raw image bytes or comparing extractions is not visual inspection. If the reviewer cannot inspect the pixels, record their extraction or mathematical findings separately, and distinguish any worker-only visual reading from independent visual verification.

For source reviews, state which findings are needed for the scoped verdict and ask the reviewer to return them, with their evidence and uncertainties, in a final report as soon as they are complete. Check consequential cross-references under the same rule for inherited readings, but leave excluded cases, adjacent claims, and redundant checks out of the assignment unless they could change the verdict or its scope.

When a source verdict compares routes, ask the reviewer for a separate finding and its basis for each route. Substituting a disputed display checks the printed route, not the value of the defining expression. An accepted theorem may supply the latter without a new proof; distinguish who checked its applicability from who checked the printed source. Before landing, compare the review findings with the verdict and resolve any conflation or state explicitly which part the review did not check.

Put a short run locator in stdout, even if nothing landed: The selector's Yah session UUID from the brief and your worker Yah session UUID from the harness context. If either is unavailable, say which instead of guessing. Gödel retains the worker handoff, not the selector's brief. For each Yah review you rely on, keep the Yah session UUID beside its findings in the accepted note or stdout handoff. For a delegated review, use the session that houses its transcript and include the agent handle returned by the harness. A bare handle or a backend dispatch ID does not locate that transcript.

If this run leaves useful work unadopted, identify in stdout the clean saved revisions needed to recover it, their bases if known, which checks ran on which artifact, and what still blocks adoption. For edits with no clean saved revision, name the workspace and files containing the intended changes. A conflicted integration tree is not the recovery source. When the previous handoff identifies a still-relevant unadopted result with no recovery pointer in the accepted notes, carry those details forward even if you selected a different check. Label it unadopted and keep it separate from the next check. Drop the pointer if accepted work has superseded the result.

For delegated work, integrate the writer's finalized campaign output, not a copy from the live dispatch workspace.

For source audits, keep note drafts in scratch until the reviews needed for the verdict have arrived. When recovering Lean with shared-note changes, verify the Lean files against the reviewed revision, and reconcile the relevant note hunks in scratch from the saved revision's diff against its original base. Do not copy a historical note wholesale. Refresh campaign status, and apply the drafts in a direct workspace on the current accepted base without overwriting intervening work. Before integrating, compare the intended note hunks with that base for unrelated edits or duplicated sections. For a notes-only candidate, check the complete revision diff against its actual integration base before adoption: Only the intended hunks and paths may differ, with no stray files such as patch backups. Use the candidate's revision diff for this check, not a full-tree archive comparison: The archive expands embedded source-revision markers even in unchanged files.

Before requesting independent Lean statement review, write the intended audit signatures, including any reusable endpoint you plan to expose. Check whether their hypotheses are needed by the accepted definitions and the reduction you will actually use, or only by a stronger result nearby. Do this quick scope check before dispatch, then develop the proof in parallel with review. Ask the reviewer to check the statement and its reduction against the actual definitions and accepted interfaces, not to write a second proof. If elaboration could resolve a consequential uncertainty, ask for a small probe of that interface rather than a proof of the endpoint. Have the reviewer return the scope and applicability findings promptly, marking any unresolved interface explicitly. If an endpoint is added or its statement changes during the proof, obtain independent review of the new statement before adoption.

For Lean work that reuses declarations across module boundaries, check the key dependencies and their signatures from the intended imports before writing the dependent proof. Probe risky uses in a small scratch module using artifacts built from the matching campaign workspace, not the durable launch checkout. Use the actual goal, binders, and local instances of the dependent statement, including an application lemma if its context differs from the definition's. A #check, a concrete specialization, or a probe that assumes an instance available only inside the definition can pass while the intended rewrite or application fails. For a multi-module change, still preflight the assembled candidate with a targeted build of the endpoint modules using their actual imports, and check the public endpoints from a fresh import. This preflight does not replace the full exact-candidate audit required for adoption.

If the incoming handoff points to the previous companion run's finished audit of an adopted revision, consider its project build cache for the first integration candidate, not just for a restack. Use the identical-input or strictly additive comparison in cmd/godel/README.md between the two exact candidates. Confirm the recorded audit passed, the cache is intact and trusted under the same toolchain and Lake dependencies, and, for additive changes, the seed has no artifacts for any added module. Copy only the project build tree into the new integration workspace if its build directory is absent; do not share a writable build directory. If the pointer, comparison, or cache check is inconclusive, audit normally without looking for other seeds. Run the full audit on the new candidate, confirm Lake builds the added modules, and compare the endpoint signatures as usual; the earlier verdict does not transfer. After a successful Lean adoption, if the audited build tree is still available, put a short Audit seed line in stdout with the full adopted revision, the exact integration workspace, and the saved successful audit log path.

Immediately before starting the full Lean audit for a candidate meant to land directly on accepted, check tool_campaign status and compare the current accepted revision with the candidate's integration base. If they differ, follow the recovery guidance in cmd/godel/README.md: Reconcile only the still-needed changes with the new tip, then audit the replacement candidate. Do not start a full audit of an already superseded candidate just to discover staleness at adoption. This check narrows the race; the adoption result still determines whether the audited candidate landed.

Before finalizing, collect the outstanding reviews and checks you rely on, and cancel work you no longer need. Report landing status from the campaign's adoption result, not a reviewer's earlier snapshot. Only the last final response becomes the next run's input. If a late result reopens the turn, give a complete replacement handoff, not an update that depends on the earlier response.`

const improveTask = `Use the Gödel run context on stdin, this companion's run history and its corresponding Yah sessions to judge the selection and procedure. Check against accepted results: Did the route test genuinely uncovered scope, and did the handoff preserve evidence and uncertainty? If you cannot connect a run with its sessions or revision, acknowledge the gap. Improve only cmd/companion's selection or procedure when the evidence warrants it. Use offline Go tests, without launching either program or its nodes, then integrate and adopt through the campaign. Leave the goal and evidence standards unchanged. Do not undertake new proof work in this role.`
